        'הסולם (transcode_profiles.go) הוא: 144p וידאו 200 kbps ואודיו 64 kbps, ‏CRF 26; ‏240p 400/64, ‏CRF 25; ‏360p 800/96, ‏CRF 23; ‏480p 1200/128, ‏CRF 23; ‏720p 2800/128, ‏CRF 22; ‏1080p 5000/192, ‏CRF 22; ‏2160p 12000/256, ‏CRF 21. כל הרמות משתמשות ב־preset veryfast מלבד 2160p, שמשתמשת ב־slow.',
