          body: 'קובץ JPEG בגודל 4032 x 3024 (12.2 מגה־פיקסל, 3.9 MB). לפיקסל המטרייה (204, 51, 51) יש גוון 0 ורוויית HSL של 0.6; כשהוא כולו בתוך "אדומים" הרוויה שלו הופכת ל־0.6 x 1.1 = 0.66, והוא מיוצא כ־(212, 43, 43). מעיל כחול ב־(51, 77, 204), גוון 230, נמצא כולו בתוך "כחולים": 0.6 x 0 = 0, והוא מיוצא כ־(128, 128, 128), עם אותה בהירות 0.5 כמו קודם. השמיים ב־(140, 191, 242), גוון 210, מקבלים משקל 0.5 מ"ציאן" ו־0.5 מ"כחולים", כך שהרוויה שלהם, 0.8, הופכת ל־0.8 x 0.5 x 0.5 = 0.2, והם מיוצאים כ־(179, 191, 204), כחול חיוור; הגדלת שני ה"רוחב" ל־60 מביאה אותם לאפור מלא. חזית חנות כתומה ב־(230, 128, 26), גוון 30, שומרת 0.8 x 1.05 x 0.5 = 0.42 ומיוצאת כ־(181, 128, 74). ייצוא ה־JPG באיכות 92 שוקל כ־5.5 MB, והוא משימה רגילה אחת.',
