      whenNotToUse: 'צבע סלקטיבי שומר על גוון בכל מקום שבו הוא מופיע, ולכן כששני עצמים חולקים צבע ורק אחד מהם צריך להישאר צבעוני, צריך מסכת "מברשת" או "רדיאלי" על הסגנון, או "בחירת נושא", ולא טווח רחב או צר יותר. זו לא הדרך לקבל מונוכרום נקי, כי טווח שנשאר על ‎+10 וחמישה טווחים על ‎-100 עדיין משאירים צבע ברבע עוצמה בתפרים; לשם כך השתמשו בעמוד השחור לבן. אם מה שאתם רוצים הוא גרסה חזקה או רכה יותר של כל הצבעים, עמוד הרוויה עושה את זה במחוון אחד, ואם המטרה היא לשנות את הצבע שנשאר ולא לשמור עליו, עברו לעמוד שינוי הצבע של עצם.',
