        'ממיר כל פיקסל לאפור עם שישה מחווני ערוצים מ־‎-200 עד 300 שקובעים כמה בהירה תהיה כל משפחת גוונים, אותה שליטה שמסנן צבעוני נתן בחדר החושך על פילם ושעורך שולחני נותן בחלונית השחור לבן שלו.',
        'מחיל עם הפתיחה את "פילם שחור לבן": משקלי ערוצים של ברירת המחדל, שכבת "עקומות" עם הנקודות (0, 0), (0.25, 0.22), (0.75, 0.78), (1, 1) שמורידה מעט את הצללים ומרימה מעט את האזורים הבהירים, ושכבת "גרעיניות" בכמות 20, גודל 1 וחספוס 50.',
