      whenNotToUse: 'אל תפנו ל־LUT כשהבעיה היא מיפוי בהירות לכל ערוץ, כי חלונית "עקומות" עושה את זה עם עד 16 נקודות שאפשר לערוך ובלי קובץ לנהל, או כשאתם רוצים רק לגוון את הצללים והאזורים הבהירים, מה שעמוד פיצול הגוונים עושה עם שני מחווני גוון. LUT של לוג לתצוגה שמוחל על JPEG שכבר מותאם לתצוגה יהרוס את הניגודיות; השתמשו במקום זאת בחלונית "בסיסי". ואם הטבלה שלכם גדולה מ־1 MB או שהיא LUT 1D, צריך להמיר אותה קודם במקום אחר.',
